var attempt = 1
while true {
    do { return try await client.call() }
    catch let error as TransientError {
        guard attempt < 5 else { throw error }
        let ceiling = min(30.0, 0.2 * pow(2.0, Double(attempt - 1)))
        let nanos = UInt64(Double.random(in: 0...ceiling) * 1_000_000_000)
        try await Task.sleep(nanoseconds: nanos)   // throws CancellationError when cancelled
        attempt += 1
    }
}
